package app.teleport.core

import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.int
import kotlinx.serialization.json.jsonArray
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive
import java.io.File
import kotlin.test.Test
import kotlin.test.assertContentEquals
import kotlin.test.assertEquals
import kotlin.test.assertFailsWith

/** Cross-platform conformance against protocol/vectors.json (generated by the TS reference). */
class VectorTest {
    private val v = Json.parseToJsonElement(File(System.getProperty("vectors")).readText()).jsonObject
    private val now = v["now"]!!.jsonPrimitive.int.toLong()

    private fun JsonObject.s(k: String) = this[k]!!.jsonPrimitive.content
    private fun keyPair(o: JsonObject) = P256.privateKey(o.s("d").unb64u()) to o.s("pub").unb64u()

    private val recipient = keyPair(v["recipient_ka"]!!.jsonObject).let { (priv, pub) -> JcaAgreementKey(priv, pub) }
    private val sender = keyPair(v["sender_ks"]!!.jsonObject).let { (priv, pub) -> JcaSigningKey(priv, pub) }
    private val cases = v["cases"]!!.jsonArray.map { it.jsonObject }

    private fun env(o: JsonObject) = Envelope.parse(o["env"].toString())

    @Test fun fingerprint() {
        assertEquals(v["sender_ks"]!!.jsonObject.s("fp"), TeleportCrypto.fingerprint(sender.publicKey))
    }

    @Test fun opensEveryCase() {
        for (c in cases) {
            val pt = TeleportCrypto.open(env(c), recipient, sender.publicKey, now)
            assertEquals(c.s("plaintext"), pt.b64u(), c.s("name"))
        }
    }

    @Test fun sealMatchesEveryCase() {
        for (c in cases) {
            val expected = env(c)
            val eph = keyPair(c["eph"]!!.jsonObject).let { (priv, pub) -> JcaAgreementKey(priv, pub) }
            val sealed = TeleportCrypto.seal(
                expected.k, c.s("plaintext").unb64u(), sender, recipient.publicKey,
                id = expected.id.unb64u(), ts = expected.ts, ephemeral = eph, nonce = expected.n.unb64u(),
            )
            assertEquals(expected.copy(sig = ""), sealed.copy(sig = ""), c.s("name"))
            // Our DER→raw signature must verify too.
            TeleportCrypto.open(sealed, recipient, sender.publicKey, now)
        }
    }

    @Test fun rejectsInvalid() {
        for (c in v["invalid"]!!.jsonArray.map { it.jsonObject }) {
            val e = assertFailsWith<OpenException>(c.s("name")) {
                TeleportCrypto.open(env(c), recipient, sender.publicKey, now)
            }
            assertEquals(c.s("error"), e.code, c.s("name"))
        }
    }

    @Test fun rejectsStale() {
        val e = assertFailsWith<OpenException> { TeleportCrypto.open(env(cases[0]), recipient, sender.publicKey, now + 2 * 86_400) }
        assertEquals("stale", e.code)
    }

    @Test fun blob() {
        val b = v["blob"]!!.jsonObject
        assertContentEquals(
            b.s("plaintext").unb64u(),
            TeleportCrypto.openBlob(b.s("ciphertext").unb64u(), b.s("key").unb64u(), b.s("n").unb64u()),
        )
    }

    @Test fun pairingCard() {
        val card = PairingCard.decode(v["pairing_card"]!!.jsonObject.s("encoded"))
        assertEquals("android", card.platform)
        assertEquals(card, PairingCard.decode(card.encoded()))
    }

    @Test fun signatureEncodingRoundTrips() {
        repeat(50) {
            val raw = sender.sign(randomBytes(32))
            assertContentEquals(raw, P256.derToRaw(P256.rawToDer(raw)))
        }
    }
}
